export function nextGeneration(liveCells: Cell[]): Cell[] {
  const isLive = (x: number, y: number): boolean =>
    liveCells.some(([lx, ly]) => lx === x && ly === y);

  const countNeighbours = (x: number, y: number): number => {
    let count = 0;
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        if (isLive(x + dx, y + dy)) count++;
      }
    }
    return count;
  };

  const candidates: Cell[] = [];
  for (const [x, y] of liveCells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        const candidate: Cell = [x + dx, y + dy];
        if (!candidates.some(([cx, cy]) => cx === candidate[0] && cy === candidate[1])) {
          candidates.push(candidate);
        }
      }
    }
  }

  return candidates.filter(([x, y]) => {
    const neighbours = countNeighbours(x, y);
    return isLive(x, y) ? neighbours === 2 || neighbours === 3 : neighbours === 3;
  });
}

